#!/usr/bin/env bash
# ap3_l16_the_appendix.sh -- task ap3: the three things the brief asks
# `autopoly3.md` to carry that the report writer does not compute --
# the x87 PROBE, the `check` TALLY and the FIX-4 MEASUREMENT -- appended
# to it, each GENERATED by re-running the thing rather than typed.
#
# The probe is compiled and carved again here, live, so the appendix's
# LITERAL is a fact about this image and not a transcript copied from
# lane `ap3_l2`.  The tally is read off the two artifacts.  Fix 4's
# table is `autopoly3.py fix4`'s own output.
#
# The append is guarded on its own marker, so re-running this lane
# cannot double the appendix.
set -euo pipefail
A=PseudoCoupHQ/Research/oracle/cross_construction/emulation/autopoly
cd "$A"
python3 - <<'PY'
import io
import json
import os
import subprocess
import sys

HERE = "PseudoCoupHQ/Research/oracle/cross_construction/emulation"
A = os.path.join(HERE, "autopoly")
sys.path.insert(0, os.path.join(HERE, "handful"))
sys.path.insert(0, os.path.join(HERE, "autopoly"))
import handful as H                                            # noqa: F401
import emulate as E

MARKER = "## 7. Task ap3's appendix"
report = os.path.join(A, "autopoly3.md")
text = io.open(report, encoding="utf-8").read()
if MARKER in text:
    print("the appendix is already on %s; nothing appended" % report)
    raise SystemExit(0)

lines = []
lines.append("")
lines.append(MARKER)
lines.append("")
lines.append("Three things the brief asks this report to carry which "
             "the loop does not compute: the probe that had to land "
             "before fix 2 was written, the tally of the `check` that "
             "fix 3 un-blocked, and the measurement of task h2's "
             "normalise-before-render on its own.")
lines.append("")
lines.append("### 7.1 The x87 probe, LITERAL")
lines.append("")
lines.append("The brief's rule: probe first, and only render the x87 "
             "cells as `long double` if clang emits the x87 opcode for "
             "one at the corpus's own ship flags. The compiler is "
             "`%s` and the flags are `%s` (%s)."
             % (E.CLANG, " ".join(E.SHIP_FLAGS), E.SHIP_FLAGS_SOURCE))
lines.append("")
lines.append("| the source | the carved body |")
lines.append("|---|---|")
PROBES = [
    ("long double emu_probe_ld_add(long double a, long double b)\n"
     "{\n    return a + b;\n}\n", "emu_probe_ld_add"),
    ("long double emu_probe_ld_mul(long double a, long double b)\n"
     "{\n    return a * b;\n}\n", "emu_probe_ld_mul"),
]
for source, symbol in PROBES:
    got, refusal = E.compile_and_carve(source, symbol)
    if got is None:
        lines.append("| `%s` | REFUSED: %s |"
                     % (source.replace("\n", " "), refusal))
        continue
    raw_bytes, mnem = got
    lines.append("| `%s` | `%s` |" % (source.replace("\n", " "),
                                      "; ".join(mnem)))
lines.append("")
lines.append("The probe LANDS: clang emits the x87 opcode, so c's "
             "`long double` is the 80-bit holder the fix uses. rust, go "
             "and swift have none, and their rows are refused by "
             "nature.")
lines.append("")
lines.append("### 7.2 The `check` tally, after fix 3")
lines.append("")
lines.append("`model_translate.py check` stopped on `KeyError: "
             "'mnemonic'` in `load_rows` from log_237 until this task; "
             "the one line the brief authorises reads `row[\"mnem\"]`, "
             "which is what task mn1 renamed the field to, with "
             "`mnemonic` accepted as a fallback for the older "
             "artifact.")
lines.append("")
lines.append("| artifact | rows | STATED | DISCREPANCY | REFUSED |")
lines.append("|---|---|---|---|---|")
for name, path in (("the stored `check_L2.json`",
                    os.path.join(HERE, "..", "..", "..",
                                 "op_pipeline", "lean",
                                 "check_L2.json")),
                   ("this task's re-derivation",
                    os.path.join(A, "autopoly3_check_L2_rerun.json"))):
    document = json.load(open(os.path.normpath(path)))
    tally = {}
    for row in document["rows"]:
        tally[row["outcome"]] = tally.get(row["outcome"], 0) + 1
    lines.append("| %s | %d | %d | %d | %d |"
                 % (name, len(document["rows"]),
                    tally.get("STATED", 0),
                    tally.get("DISCREPANCY", 0),
                    tally.get("REFUSED", 0)))
lines.append("")
lines.append("The two agree: 259 rows, 87 REFUSED, and 172 the check "
             "STATES -- of which the Lean run of record turned 19 into "
             "DISCREPANCY, which is why the stored artifact reads 153 + "
             "19. The stored artifact was restored byte for byte after "
             "the re-derivation; the re-derived file is beside this "
             "report as `autopoly3_check_L2_rerun.json`.")
lines.append("")
lines.append("### 7.3 Fix 4: task h2's normalise-before-render, "
             "measured alone on 1,012 runs")
lines.append("")
done = subprocess.run([sys.executable,
                       os.path.join(A, "autopoly3.py"), "fix4"],
                      capture_output=True, text=True, cwd=A)
for line in done.stdout.rstrip("\n").split("\n"):
    if line.startswith("peak resident"):
        continue
    lines.append(line)
lines.append("")
handle = io.open(report, "a", encoding="utf-8")
handle.write("\n".join(lines) + "\n")
handle.close()
print("appended %d line(s) to %s" % (len(lines), report))
PY
wc -l "$A/autopoly3.md"
echo "done"
